
/* 设置卡片 */
.settings-card {
  background: var(--xx-paper);
  overflow: hidden;
}

.settings-header {
  margin-bottom: 1rem;
  padding-bottom: 0.75rem;
  border-bottom: 0.0625rem solid var(--xx-border);
}

.settings-title {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--xx-ink);
  letter-spacing: 0.0625rem;
}

.settings-subtitle {
  margin: 0.25rem 0 0 0;
  font-size: 0.8125rem;
  color: var(--xx-light-cyan);
}

.settings-info {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.settings-info-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem 0;
}

.settings-info-label {
  font-size: 0.875rem;
  color: var(--xx-light-cyan);
  font-weight: 500;
}

.settings-info-value {
  font-size: 0.875rem;
  color: var(--xx-cyan);
  font-weight: 600;
}

/* 主题网格 */
.theme-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

/* 主题卡片 */
.theme-card {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.75rem;
  border-radius: 0.5rem;
  border: 0.0625rem solid var(--xx-border);
  background: var(--xx-bg);
  cursor: pointer;
  transition: all 0.25s ease;
  position: relative;

  &:hover {
    border-color: var(--xx-cyan);
    transform: translateY(-0.125rem);
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.08);
  }

  &.theme-card-active {
    border-color: var(--xx-cyan);
    background: rgba(74, 85, 104, 0.05);
  }
}

.theme-preview {
  width: 100%;
  height: 0.5rem;
  border-radius: 0.25rem;
  overflow: hidden;
}

.theme-color-bar {
  width: 100%;
  height: 100%;
}

.theme-info {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.theme-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--xx-ink);
}

.theme-desc {
  font-size: 0.75rem;
  color: var(--xx-light-cyan);
}

.theme-check {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  width: 1.5rem;
  height: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--xx-cyan);
  border-radius: 50%;
  color: white;
  font-size: 0.6875rem;
}

/* 设置按钮网格 */
.settings-grid {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* 设置按钮 */
.settings-btn {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  width: 100%;
  padding: 0.875rem;
  border-radius: 0.5rem;
  border: 0.0625rem solid var(--xx-border);
  background: var(--xx-bg);
  cursor: pointer;
  transition: all 0.25s ease;
  text-align: left;

  &:hover {
    border-color: var(--xx-cyan);
    transform: translateY(-0.125rem);
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.08);
  }

  &:active {
    transform: translateY(0);
    box-shadow: none;
  }
}

.settings-btn-icon {
  width: 2.5rem;
  height: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.5rem;
  font-size: 1.125rem;
  transition: all 0.25s ease;
}

.settings-btn-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.settings-btn-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--xx-ink);
}

.settings-btn-desc {
  font-size: 0.75rem;
  color: var(--xx-light-cyan);
}

.settings-btn-arrow {
  color: var(--xx-pale-cyan);
  font-size: 0.75rem;
  transition: all 0.25s ease;

  .settings-btn:hover & {
    color: var(--xx-cyan);
    transform: translateX(0.125rem);
  }
}

/* 主要按钮样式 */
.settings-btn-primary {
  .settings-btn-icon {
    background: linear-gradient(135deg, rgba(74, 111, 165, 0.15), rgba(74, 111, 165, 0.08));
    color: var(--xx-cyan);
  }

  &:hover .settings-btn-icon {
    background: linear-gradient(135deg, var(--xx-cyan), #3a5f95);
    color: white;
    transform: scale(1.05);
  }
}

/* 次要按钮样式 */
.settings-btn-secondary {
  .settings-btn-icon {
    background: linear-gradient(135deg, rgba(74, 85, 104, 0.1), rgba(74, 85, 104, 0.05));
    color: var(--xx-cyan);
  }

  &:hover .settings-btn-icon {
    background: linear-gradient(135deg, rgba(74, 111, 165, 0.2), rgba(74, 111, 165, 0.1));
    color: var(--xx-cyan);
    transform: scale(1.05);
  }
}

/* 响应式适配 */
@media (max-width: 375px) {
  .theme-grid {
    grid-template-columns: 1fr;
  }

  .settings-btn {
    padding: 0.75rem;
    gap: 0.75rem;
  }

  .settings-btn-icon {
    width: 2.25rem;
    height: 2.25rem;
    font-size: 1rem;
  }

  .settings-btn-title {
    font-size: 0.875rem;
  }

  .settings-btn-desc {
    font-size: 0.6875rem;
  }
}
