
.var-row-wrapper {
  width: 100%;
}

/* 行项目 */
.var-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  padding: 0.625rem 0.875rem;
  border-radius: 0.375rem;
  align-items: center;
  transition: all 0.25s ease;
  background: transparent;

  &:hover {
    background: rgba(74, 111, 165, 0.06);
  }

  &.var-row-complex {
    background: rgba(74, 111, 165, 0.04);
    border-left: 0.1875rem solid rgba(74, 111, 165, 0.2);
  }

  &.var-row-hovered {
    background: rgba(74, 111, 165, 0.08);
  }
}

/* 键名 */
.var-key {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #4a6fa5;
  font-weight: 600;
  cursor: pointer;
  font-size: 0.875rem;
  padding: 0.375rem 0;

  i {
    font-size: 0.6875rem;
    width: 1rem;
    color: #666;
    transition: transform 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  &:hover {
    color: #3a5f95;

    i {
      color: #4a6fa5;
    }
  }
}

/* 值区域 */
.var-value {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #2c2c2c;
  font-size: 0.875rem;
  padding: 0.375rem 0;
  min-width: 0;

  span {
    cursor: pointer;
    transition: color 0.2s ease;
    word-break: break-word;

    &:hover {
      color: #4a6fa5;
    }
  }
}

/* 修改状态标识 */
.var-modified {
  color: #059669;
  font-weight: 600;
  background: rgba(5, 150, 105, 0.08);
  padding: 0.25rem 0.625rem;
  border-radius: 0.375rem;
  border: 0.0625rem solid rgba(5, 150, 105, 0.2);

  &:hover {
    background: rgba(5, 150, 105, 0.12);
  }
}

/* 修改标签 */
.var-modified-tag {
  width: 1.375rem;
  height: 1.375rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(239, 68, 68, 0.12);
  color: #dc2626;
  border-radius: 50%;
  font-size: 0.625rem;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 0.0625rem solid rgba(239, 68, 68, 0.2);

  &:hover {
    background: rgba(239, 68, 68, 0.2);
    transform: scale(1.1);
  }
}

/* 复杂类型显示 */
.var-complex {
  color: #6b7280;
  font-style: italic;
  display: flex;
  align-items: center;
  gap: 0.375rem;
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  transition: all 0.2s ease;

  &:hover {
    color: #4a5568;
    background: rgba(74, 85, 104, 0.08);
  }

  i {
    font-size: 0.625rem;
    color: #6b7280;
    transition: transform 0.2s ease;
  }
}

/* 输入框 */
.var-input {
  flex: 1 1 auto;
  min-width: 0;
  border: 0.0625rem solid rgba(74, 111, 165, 0.3);
  background: white;
  border-radius: 0.375rem;
  padding: 0.4375rem 0.625rem;
  font-size: 0.875rem;
  color: #2c2c2c;
  outline: none;
  transition: all 0.25s ease;
  box-shadow: inset 0 0.0625rem 0.125rem rgba(0, 0, 0, 0.03);

  &:focus {
    border-color: #4a6fa5;
    box-shadow:
      0 0 0 0.1875rem rgba(74, 111, 165, 0.15),
      inset 0 0.0625rem 0.125rem rgba(0, 0, 0, 0.03);
  }

  &.var-input-small {
    flex: 0 1 6rem;
    min-width: 4rem;
  }
}

/* 数字加减按钮 */
.var-num-btn {
  width: 1.625rem;
  height: 1.625rem;
  border: none;
  border-radius: 0.375rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.25s ease;
  font-size: 0.6875rem;

  &:active {
    transform: scale(0.92);
  }
}

.var-num-btn-minus {
  background: linear-gradient(135deg, rgba(239, 68, 68, 0.1), rgba(239, 68, 68, 0.05));
  color: #dc2626;
  border: 0.0625rem solid rgba(239, 68, 68, 0.2);

  &:hover {
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.15), rgba(239, 68, 68, 0.1));
    box-shadow: 0 0.125rem 0.375rem rgba(239, 68, 68, 0.15);
  }
}

.var-num-btn-plus {
  background: linear-gradient(135deg, rgba(5, 150, 105, 0.1), rgba(5, 150, 105, 0.05));
  color: #059669;
  border: 0.0625rem solid rgba(5, 150, 105, 0.2);

  &:hover {
    background: linear-gradient(135deg, rgba(5, 150, 105, 0.15), rgba(5, 150, 105, 0.1));
    box-shadow: 0 0.125rem 0.375rem rgba(5, 150, 105, 0.15);
  }
}

/* 添加/删除按钮 */
.var-add-btn,
.var-remove-btn {
  width: 1.5rem;
  height: 1.5rem;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  transition: all 0.25s ease;
}

.var-add-btn {
  background: rgba(5, 150, 105, 0.12);
  color: #059669;
  border: 0.0625rem solid rgba(5, 150, 105, 0.2);

  &:hover {
    background: rgba(5, 150, 105, 0.18);
    transform: scale(1.1);
  }
}

.var-remove-btn {
  background: rgba(239, 68, 68, 0.12);
  color: #dc2626;
  border: 0.0625rem solid rgba(239, 68, 68, 0.2);

  &:hover {
    background: rgba(239, 68, 68, 0.18);
    transform: scale(1.1);
  }
}

/* 子项列表 */
.var-children {
  margin-left: 1.75rem;
  padding-left: 0.875rem;
  border-left: 0.125rem solid rgba(74, 111, 165, 0.12);
}

/* 数组项 */
.var-array-item {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  padding: 0.5rem 0.75rem;
  margin: 0.375rem 0;
  background: rgba(255, 255, 255, 0.7);
  border-radius: 0.375rem;
  border: 0.0625rem solid rgba(212, 175, 55, 0.15);
  transition: all 0.2s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.9);
    border-color: rgba(212, 175, 55, 0.25);
  }

  .var-input {
    flex: 1;
  }
}

.var-array-item-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.var-array-index {
  min-width: 1.5rem;
  font-size: 0.6875rem;
  color: #6b7280;
  font-weight: 600;
  background: rgba(74, 111, 165, 0.08);
  padding: 0.2rem 0.4375rem;
  border-radius: 0.25rem;
  text-align: center;
}

.var-array-item-children {
  margin-left: 1.75rem;
  padding-left: 0.875rem;
  border-left: 0.125rem solid rgba(74, 111, 165, 0.12);
}

.var-child-row {
  margin: 0.375rem 0;
}
