
.xx-detail-page {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.xx-detail-header {
  flex-shrink: 0;
}

.xx-back-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  border: 0.0625rem solid var(--xx-border);
  background: var(--xx-paper);
  color: var(--xx-ink);

  i {
    color: var(--xx-cyan);
  }

  &:hover {
    border-color: var(--xx-cyan);
    background: rgba(74, 85, 104, 0.03);
  }
}

.xx-detail-content {
  flex: 1;
  overflow-y: auto;
  padding-right: 0.25rem;

  &::-webkit-scrollbar {
    width: 0.25rem;
  }

  &::-webkit-scrollbar-thumb {
    background: rgba(74, 85, 104, 0.2);
    border-radius: 0.125rem;
  }
}
