
.xx-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 3rem;
  color: #718096;

  i {
    font-size: 3rem;
    opacity: 0.5;
    color: #4A5568;
  }

  span {
    font-size: 0.875rem;
  }
}

.xx-card-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.xx-card-clickable {
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    border-color: #4A5568;
  }

  &:active {
    transform: scale(0.99);
  }
}

.xx-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;

  i {
    color: #A0AEC0;
    font-size: 0.75rem;
  }
}

.xx-card-name {
  font-size: 1rem;
  font-weight: 700;
  color: #2C2C2C;
  letter-spacing: 0.0625rem;
}

.xx-card-info {
  font-size: 0.8125rem;
  color: #718096;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.xx-divider {
  color: #A0AEC0;
}
