
/* 页面头部 */
.patch-header {
  background: linear-gradient(135deg, rgba(74, 85, 104, 0.08) 0%, rgba(212, 175, 55, 0.05) 100%);
  border-bottom: 0.0625rem solid var(--xx-border);
  padding: 1rem;
}

.patch-header-content {
  display: flex;
  align-items: center;
  gap: 1rem;
}

/* 返回按钮 */
.patch-back-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
  border: 0.0625rem solid var(--xx-border);
  background: var(--xx-paper);
  color: var(--xx-ink);

  i {
    font-size: 0.875rem;
    color: var(--xx-cyan);
  }

  &:hover {
    background: rgba(74, 85, 104, 0.05);
    border-color: var(--xx-cyan);
  }
}

/* 标题区域 */
.patch-title-section {
  flex: 1;
}

.patch-title {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--xx-ink);
  letter-spacing: 0.0625rem;
}

.patch-subtitle {
  margin: 0.25rem 0 0 0;
  font-size: 0.8125rem;
  color: var(--xx-light-cyan);
}

/* 楼层信息卡片 */
.patch-info-card {
  margin-top: 1rem;
  background: rgba(74, 85, 104, 0.05);
  border: 0.0625rem solid var(--xx-border);
  border-radius: 0.5rem;
  padding: 0.75rem 1rem;
}

.patch-info-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.patch-info-header i {
  color: var(--xx-cyan);
  font-size: 1rem;
}

.patch-info-label {
  font-size: 0.875rem;
  color: var(--xx-cyan);
  font-weight: 600;
}

.patch-info-value {
  font-size: 0.875rem;
  color: var(--xx-ink);
  font-weight: 600;
}

/* 编辑卡片 */
.patch-editor-card {
  margin-top: 1rem;
  background: var(--xx-paper);
  border-radius: 0.5rem;
  border: 0.0625rem solid var(--xx-border);
  overflow: hidden;
  box-shadow: 0 0.0625rem 0.25rem rgba(0, 0, 0, 0.03);
}

.patch-editor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1rem;
  background: linear-gradient(135deg, rgba(74, 85, 104, 0.06) 0%, transparent 100%);
  border-bottom: 0.0625rem solid var(--xx-border);
}

.patch-editor-label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--xx-ink);
}

.patch-editor-actions {
  display: flex;
  gap: 0.5rem;
}

.patch-action-btn {
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.375rem;
  border: 0.0625rem solid var(--xx-border);
  background: var(--xx-paper);
  color: var(--xx-light-cyan);
  cursor: pointer;
  transition: all 0.2s ease;
  font-size: 0.875rem;

  &:hover {
    border-color: var(--xx-cyan);
    color: var(--xx-cyan);
    background: rgba(74, 85, 104, 0.05);
  }
}

/* 文本编辑区域 */
.patch-textarea {
  width: 100%;
  min-height: 20rem;
  padding: 1rem;
  border: none;
  background: var(--xx-bg);
  font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--xx-ink);
  resize: vertical;
  outline: none;
  transition: box-shadow 0.2s ease;

  &:focus {
    background: var(--xx-paper);
  }

  &::placeholder {
    color: var(--xx-pale-cyan);
  }
}

.patch-textarea-error {
  box-shadow: inset 0 0 0 0.125rem rgba(239, 68, 68, 0.2);
}

.patch-error {
  padding: 0.5rem 1rem;
  background: rgba(239, 68, 68, 0.05);
  border-top: 0.0625rem solid rgba(239, 68, 68, 0.15);
  color: #dc2626;
  font-size: 0.8125rem;
}

/* 保存区域 */
.patch-save-section {
  display: flex;
  justify-content: center;
  padding: 1rem 0;
}

.patch-save-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 2rem;
  border-radius: 0.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s ease;
  border: none;
  background: linear-gradient(135deg, var(--xx-success), #047857);
  color: white;
  box-shadow: 0 0.25rem 0.75rem rgba(5, 150, 105, 0.3);

  &:hover:not(:disabled) {
    background: linear-gradient(135deg, #047857, #065f46);
    box-shadow: 0 0.375rem 1rem rgba(5, 150, 105, 0.4);
    transform: translateY(-0.0625rem);
  }

  &:active:not(:disabled) {
    transform: translateY(0);
    box-shadow: 0 0.125rem 0.5rem rgba(5, 150, 105, 0.3);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

/* 响应式适配 */
@media (max-width: 375px) {
  .patch-header {
    padding: 0.75rem;
  }

  .patch-title {
    font-size: 1rem;
  }

  .patch-textarea {
    padding: 0.75rem;
    font-size: 0.8125rem;
  }

  .patch-save-btn {
    padding: 0.625rem 1.5rem;
    font-size: 0.875rem;
  }
}
